package frc.robot.subsystems.Kicker;

import frc.lib.mechanisms.PivotMechanism;
import frc.lib.statemachine.StateMachineSubsystem;
import frc.robot.subsystems.Kicker.KickerConstants.SystemState;
import frc.robot.subsystems.Kicker.KickerConstants.WantedState;

/**
 * Kicker: Rotates against gravity: arms, wrists, hoods, intake pivots. 0° = horizontal.
 * Generated by 3161 Robot Setup on 2026-10-15 -- edit freely; the app won't overwrite it.
 */
public class Kicker extends StateMachineSubsystem<WantedState, SystemState> {
    private final PivotMechanism kicker = register(new PivotMechanism(KickerConstants.KICKER));

    public Kicker() {
        super("Kicker", WantedState.STOW, SystemState.STOW);
    }

    @Override
    protected SystemState handleStateTransition(WantedState wanted, SystemState current) {
        if (wanted == WantedState.DEPLOY && onBumper()) return SystemState.DEPLOY;
        return kicker.isNear(targetFor(wanted)) ? arrivedState(wanted) : SystemState.MOVING;
    }

    @Override
    protected void applyState(SystemState state) {
        if (!KickerConstants.ENABLED) {
            kicker.stop();
            return;
        }
        // Deployed onto the bumper: no output, it just rests there (gravity holds
        // it down), so nothing fights a hit and it draws no power.
        if (getWantedState() == WantedState.DEPLOY && onBumper()) {
            kicker.stop();
            return;
        }
        // Always head for the wanted state's target; the system state just reports arrival.
        kicker.setPosition(targetFor(getWantedState()));
    }

    /**
     * True when DEPLOY is the bumper (DEPLOY_POSITION at the top of travel) and
     * the kicker is within BUMPER_ZONE of it. False while DEPLOY is a mid-air
     * test position.
     */
    private boolean onBumper() {
        boolean deployIsBumper = KickerConstants.DEPLOY_POSITION >= KickerConstants.KICKER.maxPosition - KickerConstants.KICKER.tolerance;
        return deployIsBumper && kicker.getPosition() >= KickerConstants.DEPLOY_POSITION - KickerConstants.BUMPER_ZONE;
    }

    /** Where each wanted state sends the kicker. */
    private static double targetFor(WantedState state) {
        return switch (state) {
            case STOW -> KickerConstants.STOW_POSITION;
            case DEPLOY -> KickerConstants.DEPLOY_POSITION;
        };
    }

    /** The system state for having arrived at a wanted state. */
    private static SystemState arrivedState(WantedState state) {
        return switch (state) {
            case STOW -> SystemState.STOW;
            case DEPLOY -> SystemState.DEPLOY;
        };
    }

    /** True once the kicker has reached the wanted state's target. */
    public boolean isAtTarget() {
        return getSystemState() != SystemState.MOVING;
    }
}
